from itertools import combinations_with_replacement
from collections import Counter

def get_prime_factors(n):
    factors = {}
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1
    return factors

solutions = []
for k in range(1, 11):
    for a_set in combinations_with_replacement(range(1, 5), k):
        M = 1
        for a in a_set:
            M *= (12 * a + 1)

        factors = get_prime_factors(M)
        exponents = list(factors.values())

        if len(factors) == k and Counter(exponents) == Counter(a_set):
            solutions.append(M)

print(sorted(list(set(solutions))))

