from sympy import isprime, primefactors
import itertools

def solve():
    solutions = []
    seen_a = set()
    for k in range(1, 8): # Increased k a bit
        for a_tuple in itertools.combinations_with_replacement(range(1, 16), k):
            if a_tuple in seen_a:
                continue
            seen_a.add(a_tuple)

            V = 1
            for a in a_tuple:
                V *= (12 * a + 1)

            factors = primefactors(V)
            if len(factors) == k:
                exponents = []
                temp_V = V
                # Need to count multiplicity
                # primefactors returns distinct primes
                for p in factors:
                    count = 0
                    while temp_V % p == 0:
                        count += 1
                        temp_V //= p
                    exponents.append(count)

                exponents.sort(reverse=True)
                if tuple(exponents) == a_tuple:
                    solutions.append(V)

    return sorted(list(set(solutions)))

print(solve())

