def solve_k2_refined():
    solutions = []
    for a1 in range(1, 20):
        for a2 in range(1, 20):
            C = (12 * a1 + 1) * (12 * a2 + 1)
            # Check if C = p1^a1 * p2^a2 for some distinct primes p1, p2
            # First, factorize C.
            temp_C = C
            factors = {}
            d = 2
            while d * d <= temp_C:
                while temp_C % d == 0:
                    factors[d] = factors.get(d, 0) + 1
                    temp_C //= d
                d += 1
            if temp_C > 1:
                factors[temp_C] = factors.get(temp_C, 0) + 1

            # We need the prime factorization of C to be p1^a1 * p2^a2.
            # This means factors must have exactly 2 keys, and their values must be a1 and a2.
            if len(factors) == 2:
                exps = sorted(factors.values())
                target_exps = sorted([a1, a2])
                if exps == target_exps:
                    solutions.append(C)
    return sorted(list(set(solutions)))

