import math
from collections import Counter
import time

def get_prime_factors(n):
    factors = Counter()
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors[d] += 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] += 1
    return factors

def solve():
    solutions = {1}
    start_time = time.time()

    def backtrack(k, start_a, current_multiset, current_P):
        if len(current_multiset) == k:
            factors = get_prime_factors(current_P)
            exponents = sorted(factors.values())
            if exponents == sorted(current_multiset):
                solutions.add(current_P)
            return

        limit = [0, 7, 14, 24, 36, 46, 56, 66][k]
        for a in range(start_a, limit + 1):
            backtrack(k, a + 1, current_multiset + [a], current_P * (12 * a + 1))

    for k in range(1, 6):
        print(f"Starting k={k}...")
        backtrack(k, 1, [], 1)
        print(f"Finished k={k}. Solutions so far: {solutions}")
        print(f"Time elapsed: {time.time() - start_time:.2f}s")

    return sorted(list(solutions))

print(solve())

