def get_tau_n_12(n):
    if n == 1:
        return 1

    # Factorize n = p1^a1 * p2^a2 * ...
    # tau(n^12) = (12*a1 + 1) * (12*a2 + 1) * ...
    factors = {}
    d = 2
    temp_n = n
    while d * d <= temp_n:
        while temp_n % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp_n //= d
        d += 1
    if temp_n > 1:
        factors[temp_n] = factors.get(temp_n, 0) + 1

    tau_val = 1
    for p in factors:
        a = factors[p]
        tau_val *= (12 * a + 1)
    return tau_val

